"""人员与派单映射（config/people.yaml）的校验、下发与核对。

为什么存在：映射曾经散在 5 处——skill 的 markdown 表、脚本里的硬编码 dict、
gitignore 掉的 wecom_user_map.json、一次性迁移方案的账号表、还有 ~/.config 下的
本机文件。任一处改了其它几处不知道。现在 config/people.yaml 是唯一 SoT，
本脚本负责「从 SoT 出发」的三件事：

  --check         自检 + 与禅道/GitLab 实际账号核对（只读）
  --emit-wecom    生成 config/wecom_user_map.json（转发器运行时读它）
  --emit-owners   生成 references/module-owners.md 的机器可读附录（给人看的正文不动）
  --push-gitlab   把本仓推到 241 GitLab（含 people.yaml）；默认 dry-run

一律 fail-closed：SoT 有问题就退出非 0，不静默兜底。
"""
from __future__ import annotations

import argparse
import json
import os
import re
import subprocess
import sys
from pathlib import Path
from typing import Any, Optional

ROOT = Path(__file__).resolve().parent.parent
SOT = ROOT / "config" / "people.yaml"
WECOM_OUT = ROOT / "config" / "wecom_user_map.json"

sys.path.insert(0, str(Path(__file__).resolve().parent))


def die(msg: str, code: int = 1) -> None:
    print(f"[people_sync] {msg}", file=sys.stderr)
    raise SystemExit(code)


def load_sot(path: Path = SOT) -> dict[str, Any]:
    if not path.is_file():
        die(f"找不到 SoT：{path}（本仓映射唯一来源，不要去读 ~/.config）", 2)
    try:
        import yaml
    except ImportError:
        die("需要 PyYAML：pip install pyyaml", 2)
    data = yaml.safe_load(path.read_text(encoding="utf-8"))
    if not isinstance(data, dict) or "people" not in data:
        die(f"{path} 结构不对：缺 people 段", 2)
    return data


# --------------------------------------------------------------------------- 查询 API
# 供其它脚本 import，避免各自再造一份表。


def name_map(data: Optional[dict] = None) -> dict[str, str]:
    """姓名 / 别名 / username → 内部 key。用于把人话解析成账号。"""
    data = data or load_sot()
    out: dict[str, str] = {}
    for key, p in (data.get("people") or {}).items():
        out[key] = key
        for field in ("name", "zentao", "gitlab"):
            v = str(p.get(field) or "").strip()
            if v:
                out[v] = key
        for alias in p.get("aliases") or []:
            out[str(alias).strip()] = key
    return out


def zentao_of(who: str, data: Optional[dict] = None) -> str:
    data = data or load_sot()
    key = name_map(data).get(str(who).strip().lstrip("@"), "")
    return str(((data.get("people") or {}).get(key) or {}).get("zentao") or "")


def gitlab_of(who: str, data: Optional[dict] = None) -> str:
    data = data or load_sot()
    key = name_map(data).get(str(who).strip().lstrip("@"), "")
    return str(((data.get("people") or {}).get(key) or {}).get("gitlab") or "")


def owner_of_text(text: str, data: Optional[dict] = None) -> tuple[str, list[str], str]:
    """按标题/正文猜主责。返回 (owner_key, cc_keys, 命中的模块名)；猜不到返回 ('', [], '')。

    命中顺序：审查单元编号 [Tn-x] 优先（硬映射），再走关键词 match。
    命中多个关键词模块时**不猜**——按 rules.no_match 交给人。
    """
    data = data or load_sot()
    mods = data.get("modules") or {}
    t = str(text or "")

    m = re.search(r"\[T(\d{1,2})-\d+\]", t)
    if m:
        unit = "T" + m.group(1)
        cfg = mods.get(unit)
        if isinstance(cfg, dict) and cfg.get("owner"):
            return str(cfg["owner"]), [str(x) for x in (cfg.get("cc") or [])], unit

    low = t.lower()
    hits: list[tuple[str, dict]] = []
    for mod, cfg in mods.items():
        if not isinstance(cfg, dict):
            continue
        for kw in cfg.get("match") or []:
            if str(kw).lower() in low:
                hits.append((mod, cfg))
                break
    if len(hits) == 1 and hits[0][1].get("owner"):
        mod, cfg = hits[0]
        return str(cfg["owner"]), [str(x) for x in (cfg.get("cc") or [])], mod
    return "", [], ""


# --------------------------------------------------------------------------- check


def cmd_check(data: dict, *, probe: bool) -> int:
    people = data.get("people") or {}
    problems: list[str] = []
    warns: list[str] = []

    keys = set(people)
    for key, p in people.items():
        if not isinstance(p, dict):
            problems.append(f"people.{key} 不是映射")
            continue
        if not p.get("name"):
            problems.append(f"people.{key} 缺 name")
        if p.get("role") not in ("human", "bot"):
            problems.append(f"people.{key}.role 必须是 human/bot，实际 {p.get('role')!r}")
        mob = str(p.get("mobile") or "")
        if mob and not re.fullmatch(r"\d{11}", mob):
            problems.append(f"people.{key}.mobile 不是 11 位数字：{mob!r}")

    # 引用完整性：modules / projects 里提到的人必须在 people 里
    for mod, cfg in (data.get("modules") or {}).items():
        if not isinstance(cfg, dict):
            continue
        own = cfg.get("owner")
        if own and own not in keys:
            problems.append(f"modules.{mod}.owner={own!r} 不在 people 里")
        for c in cfg.get("cc") or []:
            if c not in keys:
                problems.append(f"modules.{mod}.cc 含未知的 {c!r}")
    for proj, cfg in (data.get("projects") or {}).items():
        if isinstance(cfg, dict) and cfg.get("owner") and cfg["owner"] not in keys:
            problems.append(f"projects.{proj}.owner={cfg['owner']!r} 不在 people 里")

    # 反向重名：两个人共用一个禅道/GitLab 账号
    for field in ("zentao", "gitlab"):
        seen: dict[str, str] = {}
        for key, p in people.items():
            v = str((p or {}).get(field) or "")
            if not v:
                continue
            if v in seen:
                problems.append(f"{field}={v!r} 被 {seen[v]} 和 {key} 同时占用")
            seen[v] = key

    print(f"SoT: {SOT}")
    print(f"人员 {len(people)} 人（human {sum(1 for p in people.values() if p.get('role') == 'human')}"
          f" / bot {sum(1 for p in people.values() if p.get('role') == 'bot')}）")
    print(f"模块 {len(data.get('modules') or {})} 条，项目 {len(data.get('projects') or {})} 个")

    if probe:
        problems += _probe_zentao(people)
        warns += _probe_gitlab(people)

    for w in warns:
        print(f"  警告 {w}")
    if problems:
        print()
        print(f"发现 {len(problems)} 个问题：")
        for p in problems:
            print(f"  ✗ {p}")
        return 1
    print("自检通过。" + ("（含线上账号核对）" if probe else "（未探活，加 --probe 核对线上账号）"))
    return 0


def _probe_zentao(people: dict) -> list[str]:
    try:
        from zentao_client import ZenTao
    except ImportError as e:
        return [f"禅道探活跳过：{e}"]
    try:
        zt = ZenTao()
        zt.login()
        accounts = zt.user_accounts()
    except Exception as e:  # noqa: BLE001 - 探活失败不该炸掉整个 check
        return [f"禅道探活失败（不阻断）：{str(e)[:120]}"]
    bad = []
    for key, p in people.items():
        acct = str((p or {}).get("zentao") or "")
        if acct and acct not in accounts:
            bad.append(f"禅道无账号 {acct!r}（people.{key}）")
    print(f"禅道账号核对：{len(accounts)} 个账号，映射命中 "
          f"{sum(1 for p in people.values() if str(p.get('zentao') or '') in accounts)}")
    return bad


def _probe_gitlab(people: dict) -> list[str]:
    """GitLab 侧只做告警：用户可能存在但当前 token 看不到。"""
    try:
        from gitlab_client import GitLabClient
    except ImportError as e:
        return [f"GitLab 探活跳过：{e}"]
    try:
        gl = GitLabClient()
    except Exception as e:  # noqa: BLE001
        return [f"GitLab 探活跳过（不阻断）：{str(e)[:120]}"]
    out = []
    for key, p in people.items():
        un = str((p or {}).get("gitlab") or "")
        if not un:
            continue
        try:
            r = gl.get("/users", params={"username": un}) if hasattr(gl, "get") else None
            if isinstance(r, list) and not r:
                out.append(f"GitLab 查不到 {un!r}（people.{key}）")
        except Exception:  # noqa: BLE001,S110 - 查不到就算了，只是告警
            pass
    return out


# --------------------------------------------------------------------------- emit


def cmd_emit_wecom(data: dict, *, write: bool) -> int:
    """生成企微转发器要的 username → {name, mobile}。

    键用 GitLab username 小写：转发器拿 GitLab 事件里的 @username 来查，
    而 forwarder 里是 user_map.get(un.lower())。
    """
    out: dict[str, dict[str, str]] = {}
    skipped = []
    for key, p in (data.get("people") or {}).items():
        if p.get("role") != "human":
            continue
        un = str(p.get("gitlab") or p.get("zentao") or key).lower()
        mobile = str(p.get("mobile") or "")
        if not mobile:
            skipped.append(f"{key}（无手机号，群里只会 @账号不推提醒）")
            continue
        out[un] = {"name": str(p.get("name") or key), "mobile": mobile}
    body = json.dumps(out, ensure_ascii=False, indent=2) + "\n"
    if not write:
        print(body)
        print(f"# {len(out)} 人；跳过 {len(skipped)}：{'; '.join(skipped) or '无'}", file=sys.stderr)
        print("# 这是 dry-run，加 --write 才落盘", file=sys.stderr)
        return 0
    WECOM_OUT.write_text(body, encoding="utf-8")
    print(f"已写 {WECOM_OUT}（{len(out)} 人）")
    if skipped:
        print(f"跳过 {len(skipped)}：{'; '.join(skipped)}")
    return 0


def cmd_emit_owners(data: dict) -> int:
    """打印模块→主责的机器可读视图，便于人核对 SoT 与 markdown 说明是否一致。"""
    print("| 模块 | 主责 | 抄送 | 命中关键词 |")
    print("|------|------|------|------------|")
    for mod, cfg in (data.get("modules") or {}).items():
        if not isinstance(cfg, dict):
            continue
        owner = cfg.get("owner") or "（按被测模块）"
        cc = ", ".join(cfg.get("cc") or []) or "—"
        kw = ", ".join(str(x) for x in (cfg.get("match") or [])) or "（按编号硬映射）"
        print(f"| {mod} | `{owner}` | {cc} | {kw} |")
    return 0


