def _run(cmd: list[str], *, cwd: Path = ROOT) -> tuple[int, str]:
    p = subprocess.run(cmd, cwd=str(cwd), capture_output=True, text=True)
    return p.returncode, (p.stdout + p.stderr).strip()


def cmd_push_gitlab(data: dict, *, remote: str, branch: str, write: bool) -> int:
    """把本仓推到 241 GitLab。默认 dry-run —— 推送是外向操作，必须人明确同意。

    CLAUDE.md：「本地优先；推送本仓到 241 需用户明确『建仓并 push』。」
    所以这里 --write 只是解除脚本自身的保险，调用者仍须已获用户授权。
    """
    code, out = _run(["git", "rev-parse", "--abbrev-ref", "HEAD"])
    if code:
        die(f"读不到当前分支：{out}", 2)
    cur = out.strip()
    branch = branch or cur

    code, remotes = _run(["git", "remote", "-v"])
    has_remote = any(line.split()[0] == remote for line in remotes.splitlines() if line.strip())

    code, status = _run(["git", "status", "--porcelain"])
    dirty = [ln for ln in status.splitlines() if ln.strip()]

