        raise ZenTaoError("operator username 为空，无法查全局禅道凭据表")
    if "/" in name or "\\" in name or name in {".", ".."}:
        raise ZenTaoError(f"非法 operator username: {name!r}")
    return global_token_dir() / f"zentao_token.{name}"


def list_global_zentao_usernames() -> list[str]:
    folder = global_token_dir()
    if not folder.is_dir():
        return []
    out = []
    for p in sorted(folder.glob("zentao_token.*")):
        if p.is_file() and "bak" not in p.name.lower():
            suffix = p.name[len("zentao_token.") :]
            if suffix:
                out.append(suffix)
    return out


